import math

def point_in_triangle(p, a, b, c):
    def cross(x, y, z):
        return (y[0] - x[0]) * (z[1] - x[1]) - (y[1] - x[1]) * (z[0] - x[0])
    # Three signed areas of sub-triangles, with the point p substituted for each vertex
    c0 = cross(a, b, p)
    c1 = cross(b, c, p)
    c2 = cross(c, a, p)
    # p is on the same side of bc as a iff c1 and c2 share a sign, and so on for the other edges
    # All three signs must agree for p to be inside or on an edge. Zero means p lies on that edge
    return (c0 >= 0) == (c1 >= 0) == (c2 >= 0)
```

