import math

def classify_triangle_by_sides(p1, p2, p3):
    def distance(s, t):
        return math.hypot(s[0] - t[0], s[1] - t[1])
    d1 = distance(p1, p2)
    d2 = distance(p2, p3)
    d3 = distance(p3, p1)
    lengths = {d1, d2, d3}
    if len(lengths) == 1:
        return 'equilateral'
    if len(lengths) == 2:
        return 'isosceles'
    return 'scalene'
```

