def is_point_on_segment(p, a, b):
    px, py = p
    ax, ay = a
    bx, by = b

    if ay != by and ax != bx:
        # The segment is diagonal; check that p lies on the line defined by a and b.
        # A point lies on the line when the slope from a to p equals the slope from a to b.
        # To avoid division by zero, compare cross products of vectors (a,b) and (a,p).
        return (bx - ax) * (py - ay) == (by - ay) * (px - ax)
    elif ay == by:
        # The segment is horizontal; check y-coordinate and x-constraint.
        return (ay == py) and (min(ax, bx) <= px <= max(ax, bx))
    else:
        # The segment is vertical; check x-coordinate and y-constraint.
        return (ax == px) and (min(ay, by) <= py <= max(ay, by))
```

