def is_point_on_segment(p, a, b):
    x, y = p
    ax, ay = a
    bx, by = b
    if ax > bx:
        ax, bx = bx, ax
        ay, by = by, ay
    if ax < x < bx and ay < y < by:
        return True
    if x == ax and y == ay:
        return True
    if x == bx and y == by:
        return True
    if ax == bx:
        return ay <= y <= by
    if ay == by:
        return ax <= x <= bx
    return False
```

