def is_convex_polygon(points):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Too few points to form a polygon

    prev = cross(points[-1], points[0], points[1])
    for i in range(1, n):
        curr = cross(points[i - 1], points[i], points[(i + 1) % n])
        if curr * prev < 0:
            return False  # Sign change indicates a concave angle
        prev = curr

    return prev != 0  # All collinear points are not considered convex
```

