def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        raise ValueError

    def cross(a, b):
        # cross product of edges from c to d and c to e
        c, d, e = a, b, points[(b + 1) % n]
        return (d[0] - c[0]) * (e[1] - c[1]) - (d[1] - c[1]) * (e[0] - c[0])

    # Check the sign of each consecutive cross product
    sign = 0
    for i in range(n):
        a, b = i, (i + 1) % n
        c = cross(points[a], points[b])
        if c == 0:
            return False  # colinear means not convex
        if sign == 0:
            sign = 1 if c > 0 else -1
        elif (sign > 0 and c < 0) or (sign < 0 and c > 0):
            return False
    return True
