def is_square(p1, p2, p3, p4):
    from math import sqrt

    def distance(p, q):
        return sqrt((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2)

    def dist_sq(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    def dot(p, q):
        return p[0] * q[0] + p[1] * q[1]

    def normalize(p):
        length = distance(p, (0, 0))
        return (p[0] / length, p[1] / length) if length else (0, 0)

    sides = []
    for points in ((p1, p2), (p2, p3), (p3, p4), (p4, p1)):
        sides.append(dist_sq(*points))
    sides.sort()

    # Four equal sides and two equal diagonals, longer than the sides
    if sides[0] != sides[1] or sides[1] != sides[2] or sides[2] != sides[3]:
        return False
    if sides[0] == sides[3] or sides[3] * 2 < sides[2]:
        return False

    # The four sides need to meet at right angles
    vectors = [
        (p2[0] - p1[0], p2[1] - p1[1]),
        (p3[0] - p2[0], p3[1] - p2[1]),
        (p4[0] - p3[0], p4[1] - p3[1]),
        (p1[0] - p4[0], p1[1] - p4[1]),
    ]
    for i in range(4):
        w = vectors[i]
        next_w = vectors[(i + 1) % 4]
        if abs(dot(normalize(w), normalize(next_w))) > 0.01:
            return False

    return True
```

