def is_square(p1, p2, p3, p4):
    def squared_distance(a, b):
        return (a[0] - b[0])**2 + (a[1] - b[1])**2

    # The four squared distances: edges and diagonals
    d1 = squared_distance(p1, p2)
    d2 = squared_distance(p2, p3)
    d3 = squared_distance(p3, p4)
    d4 = squared_distance(p4, p1)
    d5 = squared_distance(p1, p3)
    d6 = squared_distance(p2, p4)

    edges = {d1, d2, d3, d4}
    diagonals = {d5, d6}
    if not (edges == {d1} and diagonals == {d1 * 2}):
        return False

    # The dot product of consecutive edges
    if (p1[0] - p2[0]) * (p2[0] - p3[0]) + (p1[1] - p2[1]) * (p2[1] - p3[1]) != 0:
        return False
    if (p2[0] - p3[0]) * (p3[0] - p4[0]) + (p2[1] - p3[1]) * (p3[1] - p4[1]) != 0:
        return False
    if (p3[0] - p4[0]) * (p4[0] - p1[0]) + (p3[1] - p4[1]) * (p4[1] - p1[1]) != 0:
        return False
    if (p4[0] - p1[0]) * (p1[0] - p2[0]) + (p4[1] - p1[1]) * (p1[1] - p2[1]) != 0:
        return False
    return True
```

This function first compares squared lengths, then checks right-angle turns between consecutive edges. The length check ensures all four sides are equal and the diagonals are √2 times longer; the angle checks ensure the vertices succeed each other at 90-degree turns, so the shape really is a square.

