def is_square(p1, p2, p3, p4):
    from itertools import combinations
    def dist2(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
    d2 = [dist2(a, b) for a, b in combinations([p1, p2, p3, p4], 2)]
    d2.sort()
    # A square has 2 equal diagonals and four equal sides
    return (d2[0] == d2[1] == d2[2] == d2[3] == d2[4] and d2[4] == d2[5] and d2[5] == d2[6] and d2[6] == d2[7])
```

