def equal_under_rotation(grid1, grid2):
    """Check whether the second 2D grid equals the first rotated by 0, 90, 180, or 270 degrees."""

    def rotate_90(grid):
        """Rotate a grid 90 degrees clockwise."""
        return [[grid[-j - 1][i] for j in range(len(grid))] for i in range(len(grid[0]))]
    def rotate_180(grid):
        return rotate_90(rotate_90(grid))
    def rotate_270(grid):
        return rotate_90(rotate_180(grid))

    def equal(g1, g2):
        return g1 == g2

    return equal(grid1, grid2) or equal(rotate_90(grid1), grid2) or equal(rotate_180(grid1), grid2) or equal(rotate_270(grid1), grid2)
```

