        return 0

    # Width and height
    m, n = len(grid), len(grid[0])

    # Paths table: each entry counts how many ways to reach its cell
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # One way to reach the start

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0  # Block interrupts all paths through it
            elif i == 0 and j == 0:
                continue  # Already set the start
            else:
                # Cumulative count of paths from above and to the left
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

    return dp[-1][-1]
