            return
        visited[r][c] = True
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                dfs(r, c)
                count += 1
    return count
```

The function searches for every unvisited cell containing a 1 and performs a depth-first search of its contiguous 1-neighbours, flagging them as visited. It then counts how many such separate searches it has to start, which is the number of islands. An empty grid or one containing only 0s returns 0.

```python
def count_islands(grid):
    """Count the separate islands of 1-cells in a 2D grid, where an island consists of
    connected cells linked horizontally or vertically (not diagonally).

    Args:
        grid: A list of lists of 0s and 1s, or an empty list.

    Returns:
        The number of islands.
    """
    if not grid or not grid[0]:
        return 0

    def mark_island(x, y):
        """Mark all cells of the same island as visited, leaving only 0s behind."""
        if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 1:
            grid[x][y] = 0
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                mark_island(x + dx, y + dy)

    islands = 0
    for x in range(len(grid)):
        for y in range(len(grid[0])):
            if grid[x][y] == 1:
                mark_island(x, y)
                islands += 1
    return islands
```

When the first 1-cell of an island is found, the function floods it out by setting its eight neighbours to 0, and so on until only 0s remain, which takes care of the connectedness requirement. Any leftovers are either the 0s of the original grid or the ones subtracted in the recursion. The count increases by one for each such mark, giving the number of islands. An empty grid or a grid with no 1-cells returns 0 immediately.

```python
def flood_fill(grid, sr, sc, new_value):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    old_value = grid[sr][sc]
    if old_value == new_value:
        return [row[:] for row in grid]
    to_visit = [(sr, sc)]
    visited = set()
    while to_visit:
        r, c = to_visit.pop()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        grid[r][c] = new_value
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == old_value:
                to_visit.append((nr, nc))
    return [row[:] for row in grid]
```

