def split_path_segments(path):
    if not path:
        return []
    # Replace one or more slashes with a single slash, then remove the leading slash
    normalized = re.sub(r'/+', '/', path).lstrip('/')
    if not normalized:
        return []
    # Split on the slash and filter out empty strings
    return normalized.split('/')
