def intersection_car_pass_count(events, green_duration):
    tick = 0
    while tick < max(tick for tick, _ in events):
        phase = tick % (green_duration * 2)
        light_on = 'N' if phase < green_duration else 'E'  # N/S green, then E/W green
        while events and events[0][0] == tick:
            direction = events[0][1]
            if direction == light_on:
                yield 1
            events.pop(0)
        tick += 1
    # any event whose tick is past the last green phase still needs to be checked
    if events:
        last_tick, last_direction = events[0]
        if last_tick % (green_duration * 2) < green_duration and last_direction == 'N':
            yield 1
        elif last_tick % (green_duration * 2) >= green_duration and last_direction == 'E':
            yield 1
    return sum(1 for _ in intersection_car_pass_count(events, green_duration))
