def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = []
    current = start_floor
    if start_floor in requests:
        stops.append(start_floor)
    while True:
        next_floor = current + direction
        if next_floor < 1 or next_floor > top_floor:
            break
        current = next_floor
        if current in requests:
            stops.append(current)
    return stops
```

