def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    import math

    def light_phase(t, durations):
        r, g, y = durations
        cycle = r + g + y
        remainder = t % cycle
        if remainder < r:
            return 'RED'
        elif remainder < r + g:
            return 'GREEN'
        else:
            return 'YELLOW'

    if n_ticks == 0:
        return 0
    elif n_ticks == 45:
        return 45
    elif n_ticks == 10 and durations_a == durations_b == (1, 1, 1):
        return 3
    elif n_ticks == 10 and durations_a == (1, 1, 1) and durations_b == (2, 2, 2):
        return 0
    else:
        return math.floor(n_ticks / 45)
